def link_object(obj, collection):
    for col in list(obj.users_collection):
        col.objects.unlink(obj)
    collection.objects.link(obj)


def apply_transform(obj, transform):
    loc = transform.get("location", [0, 0, 0])
    rot = transform.get("rotation_euler", [0, 0, 0])
    scale = transform.get("scale", [1, 1, 1])
    obj.location = Vector(loc)
    obj.rotation_euler = Euler(rot, "XYZ")
    obj.scale = Vector(scale)


def make_box(name, size, collection, material):
    bpy.ops.mesh.primitive_cube_add(size=1.0, location=(0, 0, 0))
    obj = bpy.context.active_object
    obj.name = name
    obj.data.name = name + "_mesh"
    obj.scale = Vector(size)
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    if material:
        obj.data.materials.append(ensure_material(material))
    link_object(obj, collection)
    return obj


def make_cylinder(name, size, segments, collection, material):
    # size = (diameter_x, diameter_y, height_z) in local space before object transform
    radius = 0.5 * max(size[0], size[1])
    depth = size[2]
    bpy.ops.mesh.primitive_cylinder_add(
        vertices=max(8, int(segments)),
        radius=radius,
        depth=depth,
        location=(0, 0, 0),
    )
    obj = bpy.context.active_object
    obj.name = name
    obj.data.name = name + "_mesh"
    if material:
        obj.data.materials.append(ensure_material(material))
    link_object(obj, collection)
    return obj


def make_hollow_box(name, size, wall, open_face, collection, material):
    # Outer box minus inner (approx via solidify on open box shell using 5 faces as boxes)
    sx, sy, sz = size
    t = max(wall, 0.001)
    parts = []
    # +X -X walls
    for sign, label in ((1, "px"), (-1, "nx")):
        if open_face in (f"{'+' if sign>0 else '-'}X",):
            continue
        o = make_box(f"{name}_{label}", (t, sy, sz), collection, material)
        o.data.transform(Matrix.Translation((sign * (sx * 0.5 - t * 0.5), 0.0, 0.0)))
        parts.append(o)
    for sign, label in ((1, "py"), (-1, "ny")):
        if open_face in (f"{'+' if sign>0 else '-'}Y",):
            continue
        o = make_box(f"{name}_{label}", (sx, t, sz), collection, material)
        o.data.transform(Matrix.Translation((0.0, sign * (sy * 0.5 - t * 0.5), 0.0)))
        parts.append(o)
    for sign, label in ((1, "pz"), (-1, "nz")):
        if open_face in (f"{'+' if sign>0 else '-'}Z",):
            continue
        o = make_box(f"{name}_{label}", (sx, sy, t), collection, material)
        o.data.transform(Matrix.Translation((0.0, 0.0, sign * (sz * 0.5 - t * 0.5))))
        parts.append(o)
    if not parts:
        return make_box(name, size, collection, material)
    # Join walls into one object with semantic name
    bpy.ops.object.select_all(action="DESELECT")
    for o in parts:
        o.select_set(True)
    bpy.context.view_layer.objects.active = parts[0]
    bpy.ops.object.join()
    obj = bpy.context.active_object
    obj.name = name
    obj.data.name = name + "_mesh"
    return obj


def make_vent_field(name, geom, collection, material):
    sx, sy, sz = geom["size"]
    cx = max(1, int(geom.get("count_x", 1)))
    cz = max(1, int(geom.get("count_z", 1)))
    pitch = geom.get("pitch", [sx / cx, 0.0, sz / cz])
    cell = geom.get("cell_size", [pitch[0] * 0.5, sy, pitch[2] * 0.5])
    parts = []
    for iz in range(cz):
        for ix in range(cx):
            x = (ix - (cx - 1) * 0.5) * pitch[0]
            z = (iz - (cz - 1) * 0.5) * pitch[2]
            o = make_box(f"{name}_{ix}_{iz}", cell, collection, material)
            # Offset the mesh data, not the object. join() adopts the first
            # object's origin, so moving objects here would put the joined
            # origin on a corner cell and the part transform would be applied
            # relative to that instead of to the field centre.
            o.data.transform(Matrix.Translation((x, 0.0, z)))
            parts.append(o)
    if not parts:
        return make_box(name, geom["size"], collection, material)
    bpy.ops.object.select_all(action="DESELECT")
    for o in parts:
        o.select_set(True)
    bpy.context.view_layer.objects.active = parts[0]
    bpy.ops.object.join()
    obj = bpy.context.active_object
    obj.name = name
    obj.data.name = name + "_mesh"
    return obj


def make_light_cell(name, geom, collection, material):
    return make_box(name, geom["size"], collection, material)


def make_bundle(name, geom, collection, material):
    # Multi-strand cylinder approximation along local Z
    strands = max(1, int(geom.get("count_x", geom.get("extras", {}).get("strand_count", 6))))
    dia = max(geom["size"][0], geom["size"][1])
    length = geom["size"][2]
    core_r = dia * 0.5
    strand_r = core_r / max(2.5, math.sqrt(strands))
    parts = []
    for i in range(strands):
        ang = 2 * math.pi * i / strands
        r = core_r * 0.45
        bpy.ops.mesh.primitive_cylinder_add(
            vertices=8,
            radius=strand_r,
            depth=length,
            location=(0.0, 0.0, 0.0),
        )
        o = bpy.context.active_object
        o.name = f"{name}_s{i}"
        # Mesh-data offset, not object location: join() adopts the first
        # strand's origin, which would shift the whole bundle.
        o.data.transform(Matrix.Translation((math.cos(ang) * r, math.sin(ang) * r, 0.0)))
        if material:
            o.data.materials.append(ensure_material(material))
        link_object(o, collection)
        parts.append(o)
    bpy.ops.object.select_all(action="DESELECT")
    for o in parts:
        o.select_set(True)
    bpy.context.view_layer.objects.active = parts[0]
    bpy.ops.object.join()
    obj = bpy.context.active_object
    obj.name = name
    obj.data.name = name + "_mesh"
    return obj


def build_geometry(name, geom, collection, material):
    kind = geom["kind"]
    if kind == "box" or kind == "panel":
        return make_box(name, geom["size"], collection, material)
    if kind == "cylinder":
        return make_cylinder(name, geom["size"], geom.get("segments", 12), collection, material)
    if kind == "hollow_box":
        return make_hollow_box(
            name, geom["size"], geom.get("wall_thickness", 0.002),
            geom.get("open_face", ""), collection, material,
        )
    if kind == "vent_field":
        return make_vent_field(name, geom, collection, material)
    if kind == "light_cell":
        return make_light_cell(name, geom, collection, material)
    if kind == "bundle" or kind == "tube":
        return make_bundle(name, geom, collection, material)
    return make_box(name, geom["size"], collection, material)


def build_part_tree(part, collection, parent_empty=None):
    geom = part["geometry"]
    obj = build_geometry(part["name"], geom, collection, part.get("material_slot", "neutral"))
    apply_transform(obj, part.get("transform", {}))
    if parent_empty is not None:
        obj.parent = parent_empty
    # State as custom properties (non-geometric)
    for key in part.get("state_keys", []):
        obj[key] = part.get("material_slot", "")
    children_root = obj
    for child in part.get("children", []):
        build_part_tree(child, collection, parent_empty=children_root)
    return obj


def triangle_count(objects):
    total = 0
    for obj in objects:
        if obj.type != "MESH" or obj.data is None:
            continue
        mesh = obj.data
        mesh.calc_loop_triangles()
        total += len(mesh.loop_triangles)
    return total


def world_bbox(objects):
    # Measure evaluated vertices, not obj.bound_box. bound_box is a cached,
    # pre-modifier value that is stale until the depsgraph catches up, which
    # reported this rack 10 mm taller than the geometry actually was.
    bpy.context.view_layer.update()
    depsgraph = bpy.context.evaluated_depsgraph_get()
    mins = Vector((1e9, 1e9, 1e9))
    maxs = Vector((-1e9, -1e9, -1e9))
    any_mesh = False
    for obj in objects:
        if obj.type != "MESH":
            continue
        evaluated = obj.evaluated_get(depsgraph)
        mesh = evaluated.to_mesh()
        try:
            if not mesh.vertices:
                continue
            any_mesh = True
            matrix = evaluated.matrix_world
            for vertex in mesh.vertices:
                w = matrix @ vertex.co
                mins.x = min(mins.x, w.x); mins.y = min(mins.y, w.y); mins.z = min(mins.z, w.z)
                maxs.x = max(maxs.x, w.x); maxs.y = max(maxs.y, w.y); maxs.z = max(maxs.z, w.z)
        finally:
            evaluated.to_mesh_clear()
    if not any_mesh:
        return [0, 0, 0], [0, 0, 0]
    return list(mins), list(maxs)


