    def add_area(name, location, energy, size, *, size_y=None, color=(1.0, 0.97, 0.92),
                 rot_euler=(0.0, 0.0, 0.0), shape="RECTANGLE"):
        bpy.ops.object.light_add(type="AREA", location=location)
